/* Hospital-owned gateway integration. No provider credentials in this client. */
let remoteConnection=null,remoteRoster=[],remoteAlerts=[],remoteEvents=[],remoteError='';
async function remoteAPI(path,method='GET',data){const r=await fetch('/api/escalation/'+path,{method,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined,cache:'no-store'});let v;try{v=await r.json()}catch{throw Error('Backend unavailable on this preview or connection. Use the published application.')}if(!r.ok)throw Error(v.error||'Backend request failed');return v}
async function refreshRemote(){try{remoteError='';remoteConnection=await remoteAPI('status');if(remoteConnection.database){const [r,a]=await Promise.all([remoteAPI('roster'),remoteAPI('alerts')]);remoteRoster=r.rows;remoteAlerts=a.rows;remoteEvents=a.events}}catch(e){remoteError=e.message}render()}
function remotePanel(){const c=remoteConnection,live=c?.database&&c?.gatewayConfigured&&c?.dispatchEnabled;return `<section class="panel" style="margin-bottom:20px"><div class="sectiontitle"><div><h2>Hospital escalation backend</h2><p>Server records and hospital gateway adapter · synthetic test cases only</p></div><button class="btn primary" onclick="refreshRemote()">Check connection / refresh</button></div><div class="notice"><b>${live?'Gateway configured — end-to-end verification still required':c?'Not ready for real dispatch':'Connection not checked'}</b><br>Patient details are not sent in notifications. This is not an approved emergency response service. Use established hospital escalation procedures.</div>${remoteError?`<p role="alert">${esc(remoteError)}</p>`:''}${c?`<div class="compactstats"><span>Database: <b>${c.database?'connected':'unavailable'}</b></span><span>Hospital gateway: <b>${c.gatewayConfigured?'configured':'not connected'}</b></span><span>Sending: <b>${c.dispatchEnabled?'enabled':'disabled'}</b></span></div><p>Background timeout escalation: <b>not connected</b>. Deadlines are calculated on refresh; no unattended paging. Watch and corridor hardware: <b>not verified</b>. An accepted request is not delivery or clinician acknowledgement.</p>`:''}<div class="actions"><button class="btn" onclick="openRemoteRoster()" ${!c?.database?'disabled':''}>Add on-call shift</button><button class="btn" onclick="openRemoteDispatch()" ${!live?'disabled':''}>Send synthetic test alert</button><button class="btn" onclick="showHospitalContract()">IT connection requirements</button></div><details><summary>On-call roster · this signed-in account</summary><div class="scroll"><table><thead><tr><th>Label / role</th><th>Channel / destination</th><th>Shift</th><th>Action</th></tr></thead><tbody>${remoteRoster.map(r=>`<tr><td>${esc(r.label)} · ${esc(r.role)}</td><td>${esc(r.channel)} · ${esc(r.destination)}</td><td>${fmt(r.starts)} → ${fmt(r.ends)}</td><td><button class="btn" onclick="removeRemoteShift('${r.id}')">Remove shift</button></td></tr>`).join('')||'<tr><td colspan="4">No server roster loaded. No recipient is assumed.</td></tr>'}</tbody></table></div></details><details><summary>Server alert log and acknowledgements</summary><div class="scroll"><table><thead><tr><th>Case / channel</th><th>Transport</th><th>Acknowledgement / deadline</th><th>Action</th></tr></thead><tbody>${remoteAlerts.map(r=>`<tr><td>${esc(r.case_ref)} · ${esc(r.channel)}</td><td>${esc(r.state)}<br>${esc(r.gateway_ref||'No acceptance reference')}</td><td>${r.ack_at?'Operator acknowledgement '+fmt(r.ack_at):r.overdue?'Overdue — use manual fallback':'No acknowledgement'}<br>Due ${fmt(r.due)}</td><td>${r.closed_at?'Closed':`<button class="btn" onclick="remoteAction('${r.id}','${r.ack_at?'close':'acknowledge'}')">${r.ack_at?'Close record':'Acknowledge as me'}</button>`}</td></tr>`).join('')||'<tr><td colspan="4">No remote alert records loaded.</td></tr>'}</tbody></table></div><p>Operator acknowledgement identifies the signed-in account; it is not a delivery receipt from the assigned physician.</p>${remoteEvents.slice(0,15).map(e=>`<p class="mini">${fmt(e.at)} · ${esc(e.action)} · ${esc(e.escalation)}</p>`).join('')}</details></section>`}
function openRemoteRoster(){openDialog('Add hospital on-call shift',`<p>Use a hospital-approved destination identifier or an authorized test recipient. One active shift per role and channel; overlaps block dispatch. Times below use this device’s local timezone.</p><form onsubmit="event.preventDefault();saveRemoteShift(this)"><div class="grid2"><label class="field">Recipient label<input name="label" required maxlength="100"></label><label class="field">Role<select name="role"><option value="physician">Physician</option><option value="icu">ICU</option></select></label><label class="field">Channel<select name="channel"><option value="push">Hospital app push</option><option value="phone">Hospital voice / phone gateway</option><option value="corridor">Corridor device gateway</option></select></label><label class="field">Hospital destination ID<input name="destination" required pattern="[A-Za-z0-9_+@.:-]{2,100}" maxlength="100"></label><label class="field">Shift starts<input name="starts" type="datetime-local" required></label><label class="field">Shift ends<input name="ends" type="datetime-local" required></label></div><p id="remoteFormError" role="alert"></p><button class="btn primary" type="submit">Save server roster</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function saveRemoteShift(form){try{const r=Object.fromEntries(new FormData(form));r.starts=new Date(r.starts).toISOString();r.ends=new Date(r.ends).toISOString();await remoteAPI('roster','POST',r);closeDialog();await refreshRemote()}catch(e){$('#remoteFormError').textContent=e.message}}
async function removeRemoteShift(id){try{await remoteAPI('roster','DELETE',{id});await refreshRemote()}catch(e){remoteError=e.message;render()}}
function openRemoteDispatch(){openDialog('Send synthetic test via hospital gateway',`<p>This sends a real notification request to the active recipient configured in the hospital roster. Use an authorized test destination. No names or clinical findings are included.</p><form onsubmit="event.preventDefault();sendRemoteTest(this)"><input name="requestKey" type="hidden" value="${crypto.randomUUID()}"><label class="field">Opaque test case reference<input name="caseRef" value="TEST-FN-01" pattern="(TEST|SIM|WALK)-[A-Za-z0-9_-]+" required maxlength="64"></label><label class="field">Role<select name="role"><option value="physician">Physician</option><option value="icu">ICU</option></select></label><label class="field">Channel<select name="channel"><option value="push">Hospital app push</option><option value="phone">Voice / phone</option><option value="corridor">Corridor device</option></select></label><label class="field">Test acknowledgement window in minutes<input name="ackMinutes" type="number" min="1" max="60" value="2" required></label><label><input type="checkbox" required> The active destination is authorized to receive this test</label><p id="remoteFormError" role="alert"></p><button class="btn primary" type="submit">Send test request</button><button class="btn" type="button" onclick="closeDialog()">Cancel</button></form>`)}
async function sendRemoteTest(form){const btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{const r=Object.fromEntries(new FormData(form));r.ackMinutes=Number(r.ackMinutes);await remoteAPI('alerts','POST',r);closeDialog();await refreshRemote()}catch(e){$('#remoteFormError').textContent=e.message+' The same form retains its idempotency key; do not create another request if delivery is unknown.';btn.disabled=false}}
async function remoteAction(id,action){try{await remoteAPI('action','POST',{id,action});await refreshRemote()}catch(e){remoteError=e.message;render()}}
function showHospitalContract(){openDialog('Hospital IT connection requirements',`<p>Provide an HTTPS gateway base URL and server authentication method through your IT team. Secrets must be configured server-side, never pasted into the app or chat. Current adapter expects bearer authentication and POST messages returning {accepted:true,messageId}. IT must adapt or approve this contract before enabling it.</p><p>Required channels: hospital mobile push or voice gateway; corridor device identifiers and acknowledgement semantics. Confirm idempotency, delivery receipt format, signed callback authentication, clinician identity, on-call roster authority, background scheduler, retries, downtime and network connectivity. The current implementation does not consume delivery callbacks or run unattended escalation.</p><p>Server settings: HOSPITAL_GATEWAY_URL, HOSPITAL_GATEWAY_TOKEN and HOSPITAL_DISPATCH_ENABLED. Sending remains disabled until IT configuration and authorized testing. No real patient workflow is enabled.</p><button class="btn" onclick="closeDialog()">Close</button>`)}
const renderBeforeRemote=render;render=function(){renderBeforeRemote();if(view==='Escalation center')$('#app').insertAdjacentHTML('afterbegin',remotePanel())};
